import 'package:flutter/material.dart';
import 'dart:convert';
import 'package:http/http.dart' as http;

void main() {
  runApp(const InstagramClone());
}

class InstagramClone extends StatelessWidget {
  const InstagramClone({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        brightness: Brightness.light,
        primaryColor: Colors.white,
        scaffoldBackgroundColor: Colors.white,
      ),
      home: const FeedScreen(),
    );
  }
}

class FeedScreen extends StatefulWidget {
  const FeedScreen({super.key});

  @override
  State<FeedScreen> createState() => _FeedScreenState();
}

class _FeedScreenState extends State<FeedScreen> {
  final List<dynamic> _posts = [];
  final ScrollController _scrollController = ScrollController();

  int _page = 1;
  bool _isLoading = false;
  bool _hasMore = true;

  @override
  void initState() {
    super.initState();
    _fetchPosts();

    // Listener for "Endless Scrolling"
    _scrollController.addListener(() {
      if (_scrollController.position.pixels >= _scrollController.position.maxScrollExtent * 0.9) {
        if (!_isLoading && _hasMore) {
          _fetchPosts();
        }
      }
    });
  }

  // Fetch logic with pagination
  Future<void> _fetchPosts({bool refresh = false}) async {
    if (refresh) {
      setState(() {
        _page = 1;
        _hasMore = true;
      });
    }

    setState(() => _isLoading = true);

    try {
      // Fetching from Picsum API (limit 10 per page)
      final response = await http.get(
        Uri.parse('https://picsum.photos/v2/list?page=$_page&limit=10'),
      );

      if (response.statusCode == 200) {
        List newPosts = json.decode(response.body);
        setState(() {
          if (refresh) _posts.clear();
          _posts.addAll(newPosts);
          _page++;
          if (newPosts.length < 10) _hasMore = false;
        });
      }
    } catch (e) {
      debugPrint("Error fetching posts: $e");
    } finally {
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text(
          'Instagram',
          style: TextStyle(fontFamily: 'Billabong', fontSize: 30, color: Colors.black),
        ),
        backgroundColor: Colors.white,
        elevation: 0.5,
        actions: [
          IconButton(icon: const Icon(Icons.favorite_border, color: Colors.black), onPressed: () {}),
          IconButton(icon: const Icon(Icons.send_outlined, color: Colors.black), onPressed: () {}),
        ],
      ),
      body: RefreshIndicator(
        onRefresh: () => _fetchPosts(refresh: true),
        color: Colors.grey,
        child: ListView.builder(
          controller: _scrollController,
          itemCount: _posts.length + (_hasMore ? 1 : 0),
          itemBuilder: (context, index) {
            if (index == _posts.length) {
              return const Padding(
                padding: EdgeInsets.symmetric(vertical: 32),
                child: Center(child: CircularProgressIndicator(strokeWidth: 2)),
              );
            }

            final post = _posts[index];
            return PostItem(post: post);
          },
        ),
      ),
    );
  }

  @override
  void dispose() {
    _scrollController.dispose();
    super.dispose();
  }
}

class PostItem extends StatelessWidget {
  final dynamic post;
  const PostItem({super.key, required this.post});

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // User Header
        Padding(
          padding: const EdgeInsets.all(10.0),
          child: Row(
            children: [
              const CircleAvatar(
                backgroundImage: NetworkImage('https://i.pravatar.cc/150?u=fakeuser'),
                radius: 18,
              ),
              const SizedBox(width: 10),
              Text(
                post['author'],
                style: const TextStyle(fontWeight: FontWeight.bold),
              ),
              const Spacer(),
              const Icon(Icons.more_vert),
            ],
          ),
        ),
        // Main Image
        AspectRatio(
          aspectRatio: 1,
          child: Image.network(
            post['download_url'],
            fit: BoxFit.cover,
            loadingBuilder: (context, child, loadingProgress) {
              if (loadingProgress == null) return child;
              return Container(color: Colors.grey[200]);
            },
          ),
        ),
        // Action Buttons
        Row(
          children: [
            IconButton(icon: const Icon(Icons.favorite_border), onPressed: () {}),
            IconButton(icon: const Icon(Icons.chat_bubble_outline), onPressed: () {}),
            IconButton(icon: const Icon(Icons.send_outlined), onPressed: () {}),
            const Spacer(),
            IconButton(icon: const Icon(Icons.bookmark_border), onPressed: () {}),
          ],
        ),
        // Likes & Captions
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 12.0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Liked by flutter_dev and others', style: TextStyle(fontWeight: FontWeight.bold)),
              const SizedBox(height: 5),
              RichText(
                text: TextSpan(
                  style: const TextStyle(color: Colors.black),
                  children: [
                    TextSpan(text: post['author'], style: const TextStyle(fontWeight: FontWeight.bold)),
                    const TextSpan(text: '  Captured this amazing shot with my new lens! #photography #nature'),
                  ],
                ),
              ),
              const SizedBox(height: 5),
              Text('View all 12 comments', style: TextStyle(color: Colors.grey[600], fontSize: 14)),
              const SizedBox(height: 15),
            ],
          ),
        ),
      ],
    );
  }
}

