@Composable
fun AsyncImage(model: String, modifier: Modifier = Modifier, contentDescription: String? = null, contentScale: ContentScale = ContentScale.Crop) {
    val painter = rememberAsyncImagePainter(
        model = ImageRequest.Builder(LocalContext.current)
            .data(model)
            .crossfade(true)
            .build()
    )

    Box(modifier = modifier) {
        when (painter.state) {
            is coil.compose.AsyncImagePainter.State.Loading -> {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    CircularProgressIndicator(color = Color.White, modifier = Modifier.size(32.dp))
                }
            }
            is coil.compose.AsyncImagePainter.State.Error -> {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(Color(0xFF1A1A1A)),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(Icons.BrokenImage, tint = Color.Gray, modifier = Modifier.size(50.dp))
                }
            }
            else -> {
                Image(
                    painter = painter,
                    contentDescription = contentDescription,
                    modifier = Modifier.fillMaxSize(),
                    contentScale = contentScale
                )
            }
        }
    }
}

// Data Models
data class Post(
    val id: String,
    val author: String,
    val imageUrl: String,
    val likesCount: Int,
    val commentsCount: Int,
    val caption: String,
    val timeAgo: String
)

// API Service
interface PicsumApiService {
    @GET("v2/list")
    suspend fun getPosts(
        @Query("page") page: Int,
        @Query("limit") limit: Int
    ): List<ApiPost>
}

data class ApiPost(
    val id: String,
    val author: String,
    val download_url: String
)

// Paging Source
class PostPagingSource : PagingSource<Int, Post>() {
    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, Post> {
        return try {
            val page = params.key ?: 1
            val retrofit = Retrofit.Builder()
                .baseUrl("https://picsum.photos/")
                .addConverterFactory(GsonConverterFactory.create())
                .build()
            val service = retrofit.create(PicsumApiService::class.java)
            val response = service.getPosts(page, params.loadSize)

            val posts = response.mapIndexed { index, apiPost ->
                Post(
                    id = apiPost.id,
                    author = "user_${apiPost.author.replace(" ", "_")}",
                    imageUrl = apiPost.download_url,
                    likesCount = (apiPost.id.toIntOrNull()?.rem(500) ?: 100) + 100,
                    commentsCount = (apiPost.id.toIntOrNull()?.rem(50) ?: 5) + 5,
                    caption = getRandomCaption(apiPost.id.toIntOrNull() ?: index),
                    timeAgo = "${(apiPost.id.toIntOrNull()?.rem(23) ?: 1) + 1} HOURS AGO"
                )
            }

            LoadResult.Page(
                data = posts,
                prevKey = if (page == 1) null else page - 1,
                nextKey = if (posts.isEmpty()) null else page + 1
            )
        } catch (e: Exception) {
            LoadResult.Error(e)
        }
    }

    override fun getRefreshKey(state: PagingState<Int, Post>): Int? {
        return state.anchorPosition?.let { anchorPosition ->
            state.closestPageToPosition(anchorPosition)?.prevKey?.plus(1)
                ?: state.closestPageToPosition(anchorPosition)?.nextKey?.minus(1)
        }
    }

    private fun getRandomCaption(seed: Int): String {
        val captions = listOf(
            "Amazing view! 😍",
            "Living my best life ✨",
            "Weekend vibes 🎉",
            "Feeling blessed 🙏",
            "New adventure 🌟",
            "Just another day in paradise 🌴",
            "Making memories 📸",
            "Good times and tan lines ☀️",
            "Chasing sunsets 🌅",
            "Happiness is a journey 🚀"
        )
        return captions[seed % captions.size]
    }
}

