    var posts by remember { mutableStateOf(listOf<Post>()) }
    var page by remember { mutableIntStateOf(1) }
    var isRefreshing by remember { mutableStateOf(false) }
    var isLoadingMore by remember { mutableStateOf(false) }

    val listState = rememberLazyListState()

    // Initial Fetch
    LaunchedEffect(Unit) {
        posts = retrofitApi.getPosts(page)
    }

    // Pagination Logic: Trigger when user is near bottom
    val shouldLoadMore = remember {
        derivedStateOf {
            val lastVisibleItem = listState.layoutInfo.visibleItemsInfo.lastOrNull()
            lastVisibleItem != null && lastVisibleItem.index >= posts.size - 2
        }
    }

    LaunchedEffect(shouldLoadMore.value) {
        if (shouldLoadMore.value && !isLoadingMore && posts.isNotEmpty()) {
            isLoadingMore = true
            val newPosts = retrofitApi.getPosts(++page)
            posts = posts + newPosts
            isLoadingMore = false
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Instagram", fontWeight = FontWeight.Bold, fontSize = 22.sp) },
                actions = {
